#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    getline(cin, line);
    istringstream iss(line);
    int n;
    long long k;
    iss >> n >> k;

    const long long mod = 998244353LL;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> fact(n + 1, 1);
    vector<long long> invFact(n + 1, 1);

    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }

    auto modPow = [](long long base, long long exp) -> long long {
        long long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    invFact[n] = modPow(fact[n], mod - 2);
    for (int i = n - 1; i >= 1; i--) {
        invFact[i] = ((i + 1) * invFact[i + 1]) % mod;
    }

    auto nCr = [&](int n, int r) -> long long {
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
    };

    if (k == 0) {
        cout << fact[n] << "\n";
        return 0;
    }

    int r = n - (int)k;
    long long total = 0;
    int sign = 1;

    for (int i = 0; i < r; i++) {
        long long comb = nCr(r, i);
        long long val = modPow(r - i, n);
        total = (total + sign * comb % mod * val % mod + mod) % mod;
        sign *= -1;
    }

    long long res = (2 * nCr(n, r) % mod * total) % mod;
    cout << res << "\n";

    return 0;
}

